create table if not exists public.ses_kuyrugu (key text primary key, metin text not null, tur text not null, sure numeric);
alter table public.ses_kuyrugu enable row level security;
revoke all on public.ses_kuyrugu from anon, authenticated;
insert into public.ses_kuyrugu select x->>'k', x->>'m', x->>'t', (x->>'s')::numeric from jsonb_array_elements($j$[{"k":"pi_dogru_1","m":"Harika!","t":"ses","s":null},{"k":"pi_dogru_2","m":"Süpersin!","t":"ses","s":null},{"k":"pi_dogru_3","m":"Mükemmel!","t":"ses","s":null},{"k":"pi_dogru_4","m":"Tam isabet!","t":"ses","s":null},{"k":"pi_dogru_5","m":"Bravo!","t":"ses","s":null},{"k":"pi_dogru_6","m":"Çok iyi!","t":"ses","s":null},{"k":"pi_dogru_7","m":"İşte bu!","t":"ses","s":null},{"k":"pi_dogru_8","m":"Matematik dehası!","t":"ses","s":null},{"k":"pi_dogru_9","m":"Şahane!","t":"ses","s":null},{"k":"pi_dogru_10","m":"Kafana sağlık!","t":"ses","s":null},{"k":"pi_telafi_1","m":"Hatandan öğrendin!","t":"ses","s":null},{"k":"pi_telafi_2","m":"İşte gerçek öğrenme bu!","t":"ses","s":null},{"k":"pi_telafi_3","m":"Geri döndün, harika!","t":"ses","s":null},{"k":"pi_telafi_4","m":"Gördün mü, yapabiliyorsun!","t":"ses","s":null},{"k":"pi_yanlis_1","m":"Sorun değil, birlikte bakalım.","t":"ses","s":null},{"k":"pi_yanlis_2","m":"Hata yapmak öğrenmenin parçası.","t":"ses","s":null},{"k":"pi_yanlis_3","m":"Neredeyse! Şimdi nedenine bakalım.","t":"ses","s":null},{"k":"pi_yanlis_4","m":"Hiç dert etme, bir daha deneyeceğiz.","t":"ses","s":null},{"k":"pi_yanlis_5","m":"Bu soru biraz zordu, ama sen pes etmezsin.","t":"ses","s":null},{"k":"pi_yanlis_6","m":"Güzel denemeydi! Gel, birlikte çözelim.","t":"ses","s":null},{"k":"pi_aciklama_1","m":"Gel, nerede karıştığına birlikte bakalım.","t":"ses","s":null},{"k":"pi_aciklama_2","m":"Şuraya bir bak, bence burada küçük bir karışıklık oldu.","t":"ses","s":null},{"k":"pi_telafi_soru_1","m":"Şimdi benzer ama biraz daha kolay bir soru geliyor. Sen yaparsın!","t":"ses","s":null},{"k":"pi_telafi_soru_2","m":"Hadi bir daha deneyelim, bu sefer olacak!","t":"ses","s":null},{"k":"pi_yonlendir_1","m":"Takıldın mı? Ampule dokunursan sana ipucu veririm.","t":"ses","s":null},{"k":"pi_yonlendir_2","m":"Acele etme, düşünmek de öğrenmektir.","t":"ses","s":null},{"k":"pi_yonlendir_3","m":"Soruyu bir daha oku, bazen cevap orada saklıdır.","t":"ses","s":null},{"k":"pi_ipucu_1","m":"Bak, sana küçük bir ipucu.","t":"ses","s":null},{"k":"pi_ipucu_2","m":"İşte bir ipucu, gerisi sende!","t":"ses","s":null},{"k":"pi_ders_basla_1","m":"Hadi başlayalım!","t":"ses","s":null},{"k":"pi_ders_basla_2","m":"Bugün beynini çalıştırma zamanı!","t":"ses","s":null},{"k":"pi_ders_basla_3","m":"Hazır mısın? Başlıyoruz!","t":"ses","s":null},{"k":"pi_yari_1","m":"Yarıyı geçtin, harika gidiyorsun!","t":"ses","s":null},{"k":"pi_yari_2","m":"Yarı yoldayız, devam!","t":"ses","s":null},{"k":"pi_hosgeldin_geri_1","m":"Tekrar hoş geldin! Kaldığımız yerden devam edelim mi?","t":"ses","s":null},{"k":"pi_hosgeldin_geri_2","m":"Seni özledim! Hadi biraz matematik yapalım.","t":"ses","s":null},{"k":"pi_hosgeldin_geri_3","m":"Yine geldin, süpersin! Bugün ne öğreniyoruz?","t":"ses","s":null},{"k":"pi_sinav_1","m":"Tema sınavı başlıyor. Sakin ol, sen buna hazırsın!","t":"ses","s":null},{"k":"pi_kupa_1","m":"Kupa senin! Bu temanın ustası oldun!","t":"ses","s":null},{"k":"pi_gorev_1","m":"Bir görevi daha tamamladın, ödülünü al!","t":"ses","s":null},{"k":"pi_seri3_1","m":"Üç doğru üst üste! Seri ateşi yandı!","t":"ses","s":null},{"k":"pi_seri3_2","m":"Seri başladı, devam!","t":"ses","s":null},{"k":"pi_seri5_1","m":"Durdurulamazsın!","t":"ses","s":null},{"k":"pi_seri5_2","m":"Beş doğru üst üste! İnanılmaz!","t":"ses","s":null},{"k":"pi_seri8_1","m":"Efsane! Gerçek bir matematik ustasısın!","t":"ses","s":null},{"k":"pi_seri8_2","m":"Bu seri efsanelere yakışır!","t":"ses","s":null},{"k":"pi_bitti_1","m":"Ders bitti, harika çalıştın!","t":"ses","s":null},{"k":"pi_bitti_2","m":"Bugün beynin biraz daha güçlendi!","t":"ses","s":null},{"k":"pi_bitti_3","m":"Bir adım daha ileridesin, aferin!","t":"ses","s":null},{"k":"pi_rekor_1","m":"Süre doldu! Bakalım rekoru kırdın mı?","t":"ses","s":null},{"k":"pi_rekor_2","m":"Şimşek gibiydin!","t":"ses","s":null},{"k":"pi_hosgeldin_1","m":"Merhaba, ben Pi! Beşinci sınıf matematiğini seninle oyun gibi öğreneceğiz. Her öğrenci başka bir çiçektir; ben de sana en uygun yolu bulacağım.","t":"ses","s":null},{"k":"pi_kart_1","m":"Önce sana bu konuyu anlatayım. Olmazsa başka türlü anlatırım!","t":"ses","s":null},{"k":"kart_g_temel_gorsel","m":"Uçlarına bak! İki uç noktası olan doğru parçası, bir başlangıcı ve tek oku olan ışın, iki yönde oku olan doğrudur.","t":"ses","s":null},{"k":"kart_g_temel_hikaye","m":"Ela evden okula yürüdü: evi ve okulu belli, yani yolu bir doğru parçası. Bir el feneri yaktı: ışık fenerden başlayıp tek yönde sonsuza gidiyor, bu bir ışın. Uzayda iki yönde de bitmeyen bir yol düşün: bu da bir doğru!","t":"ses","s":null},{"k":"kart_g_temel_adim","m":"Çizimin uçlarına bak. İki uç noktası varsa doğru parçasıdır. Bir uç noktası ve tek ok varsa ışındır. İki yönde ok varsa doğrudur.","t":"ses","s":null},{"k":"kart_g_temel_kural","m":"Doğru parçasının iki ucu, ışının bir ucu vardır. Doğrunun hiç ucu yoktur.","t":"ses","s":null},{"k":"kart_g_cember_gorsel","m":"Merkezden çembere giden çizgi yarıçaptır. Merkezden geçip iki ucu çemberde olan çizgi çaptır. Çap eşittir 2 çarpı yarıçap.","t":"ses","s":null},{"k":"kart_g_cember_hikaye","m":"Kerem bahçeye bir kazık çaktı, ipin ucunu bağladı ve gerilmiş iple etrafında döndü. İzi çember, kazık merkez, ip ise yarıçap! Kerem bir uçtan merkezden geçerek diğer uca yürüdüğünde ipin 2 katını yürüdü: bu da çap.","t":"ses","s":null},{"k":"kart_g_cember_adim","m":"Merkezi bul (O noktası). Merkezden çembere olan uzaklık yarıçaptır (r). Çap merkezden geçer ve 2 yarıçap uzunluğundadır. Çap verilirse yarıçap eşittir çap bölü 2.","t":"ses","s":null},{"k":"kart_g_cember_kural","m":"Çap eşittir 2 çarpı yarıçap. Çember sadece kenar çizgisi, daire ise çember artı iç bölgedir.","t":"ses","s":null},{"k":"kart_g_dikme_paralel_gorsel","m":"Köşede küçük bir kare varsa doğrular diktir. Hiç kesişmeyen, arası hep aynı olan doğrular paraleldir.","t":"ses","s":null},{"k":"kart_g_dikme_paralel_hikaye","m":"Tren rayları hiç birleşmez, aralarındaki mesafe hep aynıdır: paralel! Bir defterin kenarları köşede dik açı yapar: dik! Defteri çevirsen bile köşe hâlâ diktir.","t":"ses","s":null},{"k":"kart_g_dikme_paralel_adim","m":"İki doğru kesişiyor mu? Bak. Kesişmiyorsa ve aralarındaki uzaklık hep aynıysa, paralel. Kesişiyorsa köşedeki açıya bak. Açı 90 derece (küçük kare işareti) ise, dik. Şekil dönük olsa da kural değişmez.","t":"ses","s":null},{"k":"kart_g_dikme_paralel_kural","m":"Dik doğrular 90 derece ile kesişir. Paralel doğrular hiç kesişmez. Aynı doğruya dik iki doğru birbirine paraleldir.","t":"ses","s":null},{"k":"kart_g_aci_gorsel","m":"Açının büyüklüğü kolların ne kadar açıldığına bağlıdır, uzunluğuna değil. 90 derece (dik açı) referans noktandır.","t":"ses","s":null},{"k":"kart_g_aci_hikaye","m":"Saat tam 3'te akrep ve yelkovan dik açı yapar (90 derece). Saat 1'de aralarındaki açı daha kapalı: dar açı. Saat 5'te iyice açılır: geniş açı. Saat 6'da düz bir çizgi: doğru açı (180 derece)!","t":"ses","s":null},{"k":"kart_g_aci_adim","m":"Açıyı bir dik açıyla (defter köşesi) karşılaştır. Daha kapalıysa dar açı (90 dereceden küçük). Tam köşe gibiyse dik açı (90 derece). Daha açıksa geniş açı (90 ile 180 derece). İletkiyle ölçerken kolun başladığı 0'ın olduğu ölçeği oku.","t":"ses","s":null},{"k":"kart_g_aci_kural","m":"Dar açı 90 dereceden küçüktür. Dik açı tam 90 derecedir. Geniş açı 90 ile 180 derece arasındadır. Doğru açı 180, tam açı 360 derecedir.","t":"ses","s":null},{"k":"kart_g_aci_iliski_gorsel","m":"Kesişen iki doğruda karşı karşıya duran açılar ( ters açılar ) eşittir. Yan yana olan açılar toplamı 180 derecedir.","t":"ses","s":null},{"k":"kart_g_aci_iliski_hikaye","m":"Makas açtığında iki bıçak bir X oluşturur. Üstteki açı ne kadarsa alttaki de o kadardır: ters açılar hep ikizdir! Bir pizza dilimini dik köşeden kesersen iki parçanın açıları toplamı 90 derece olur: tümler.","t":"ses","s":null},{"k":"kart_g_aci_iliski_adim","m":"Tümler mi bütünler mi soruluyor? Bak. Tümler: toplam 90 derece, 90 eksi verilen. Bütünler: toplam 180 derece, 180 eksi verilen. Ters açı: karşıdaki açı, aynı ölçü.","t":"ses","s":null},{"k":"kart_g_aci_iliski_kural","m":"Tümler eşittir 90 derece, Bütünler eşittir 180 derece, Ters açılar eşittir.","t":"ses","s":null},{"k":"kart_g_cokgen_gorsel","m":"Çokgende kenar eşittir köşe eşittir iç açı sayısı. Köşegen, yan yana olmayan iki köşeyi birleştirir.","t":"ses","s":null},{"k":"kart_g_cokgen_hikaye","m":"Arılar peteklerini düzgün altıgen yapar: 6 kenar, 6 köşe, 6 iç açı, hepsi eşit! Bir köşeden köşegen çizmek istersen kendine ve iki komşuna çizemezsin, geriye 6 eksi 3 eşittir 3 köşe kalır.","t":"ses","s":null},{"k":"kart_g_cokgen_adim","m":"Kenarları say, çokgenin adı (5, beşgen). Köşe ve iç açı sayısı kenar sayısına eşittir. Bir köşeden köşegen: köşe sayısı eksi 3. Düzgün çokgen: kenarlar eşit artı açılar eşit.","t":"ses","s":null},{"k":"kart_g_cokgen_kural","m":"n kenarlı çokgen: n köşe, n iç açı; bir köşeden (n eksi 3) köşegen.","t":"ses","s":null},{"k":"kart_g_ucgen_gorsel","m":"Üçgenin üç iç açısını yan yana koyarsan bir doğru açı (180 derece) oluşur.","t":"ses","s":null},{"k":"kart_g_ucgen_hikaye","m":"Defne kâğıttan bir üçgen kesti, üç köşesini yırtıp yan yana dizdi. Şaşırdı: köşeler tam bir düz çizgi oluşturdu! Her üçgende iç açılar toplamı 180 derece.","t":"ses","s":null},{"k":"kart_g_ucgen_adim","m":"İki açı verildiyse topla. 180'den çıkar, üçüncü açı. Türünü bulmak için EN BÜYÜK açıya bak. 90 dereceden büyükse geniş, tam 90 derece ise dik, hepsi küçükse dar açılı.","t":"ses","s":null},{"k":"kart_g_ucgen_kural","m":"İç açılar toplamı 180 derece. Eşkenar üçgende her açı 60 derece. İkizkenarda taban açıları eşit.","t":"ses","s":null},{"k":"kart_n_okuma_gorsel","m":"Sayıyı sağdan üçerli bölüklere ayır: milyarlar, milyonlar, binler, birler. Her bölüğü oku, adını ekle.","t":"ses","s":null},{"k":"kart_n_okuma_hikaye","m":"Emre, Neptün'ün Güneş'e uzaklığını okumak istedi ama sayı çok uzundu! Sağdan üçer üçer ayırdı, her gruba bir isim verdi: birler, binler, milyonlar. Birden sayı kolayca okunur hâle geldi.","t":"ses","s":null},{"k":"kart_n_okuma_adim","m":"Sayıyı sağdan üçerli ayır. Bölük adlarını yaz: birler, bin, milyon, milyar. Soldan başlayarak her bölüğü oku ve adını söyle. 000 olan bölüğün adı okunmaz. Yazarken okunmayan basamaklara 0 koy.","t":"ses","s":null},{"k":"kart_n_okuma_kural","m":"Her bölük 3 basamak. Bin önünde bir söylenmez; bir milyon söylenir.","t":"ses","s":null},{"k":"kart_n_basamak_gorsel","m":"Rakamın değeri bulunduğu yere göre değişir: 5, yüzler basamağında 500, binler basamağında 5000 değerindedir.","t":"ses","s":null},{"k":"kart_n_basamak_hikaye","m":"Bir sinemada aynı koltuk numarası farklı sıralarda farklı yerdir. Rakamlar da öyle: aynı 7, birler sırasında 7, on binler sırasında 70000 eder!","t":"ses","s":null},{"k":"kart_n_basamak_adim","m":"Rakamın hangi basamakta olduğunu sağdan sayarak bul. O basamağın değerini yaz (1, 10, 100, 1000. ). Rakam çarpı basamak değeri eşittir basamak değeri. Çözümleme: sayıyı basamak değerlerinin toplamı olarak yaz.","t":"ses","s":null},{"k":"kart_n_basamak_kural","m":"Basamak değeri eşittir rakam çarpı basamağın değeri. 4725 eşittir 4000 artı 700 artı 20 artı 5.","t":"ses","s":null},{"k":"kart_n_karsilastir_gorsel","m":"Önce basamak sayısına bak; basamağı fazla olan büyüktür. Eşitse soldan rakam rakam karşılaştır.","t":"ses","s":null},{"k":"kart_n_karsilastir_hikaye","m":"İki kardeş kumbaralarını saydı. Ali'nin parası 9999 TL, Ece'ninki 10000 TL. Ali benimki 9 ile başlıyor, daha büyük! dedi. Ece güldü: Benim sayım 5 basamaklı, seninki 4!","t":"ses","s":null},{"k":"kart_n_karsilastir_adim","m":"Basamak sayılarını karşılaştır. Fazla olan büyüktür. Eşitse en soldaki rakamlardan başla. İlk farklı rakamı büyük olan sayı büyüktür.","t":"ses","s":null},{"k":"kart_n_karsilastir_kural","m":"Önce uzunluk, sonra soldan ilk farklı rakam.","t":"ses","s":null},{"k":"kart_n_toplacikar_gorsel","m":"Toplama ve çıkarma birbirinin tersidir: 25 artı 15 eşittir 40 ise 40 eksi 15 eşittir 25.","t":"ses","s":null},{"k":"kart_n_toplacikar_hikaye","m":"Suzan bir çıkarma işleminde eksileni sildi. Kardeşi Nazlı düşündü: Bir şeyden 15 çıkınca 25 kaldıysa, başta 25 artı 15 eşittir 40 vardı! Ters işlem, kayıp sayıyı buldu.","t":"ses","s":null},{"k":"kart_n_toplacikar_adim","m":"Basamakları hizalayarak alt alta yaz. Birlerden başla. Toplamada 10'u geçerse eldeyi taşı. Çıkarmada üstteki küçükse onluk boz. Bilinmeyen terim için ters işlemi kullan.","t":"ses","s":null},{"k":"kart_n_toplacikar_kural","m":"Bilinmeyen terim eşittir toplam eksi diğer terim. Eksilen eşittir çıkan artı fark.","t":"ses","s":null},{"k":"kart_n_carpbol_gorsel","m":"Sıfırları ayır, kalanları çarp, sıfırları geri ekle: 32 çarpı 300, 32 çarpı 3 eşittir 96, 9600.","t":"ses","s":null},{"k":"kart_n_carpbol_hikaye","m":"Tahir hesap makinesiz bir hile keşfetti: 6000 bölü 20 için iki sayıdan da birer sıfır sildi, 600 bölü 2 eşittir 300 buldu. Sıfırlar hem bölünende hem bölende olduğu için silmek sonucu değiştirmedi!","t":"ses","s":null},{"k":"kart_n_carpbol_adim","m":"Sondaki sıfırları say. Çarpmada: sıfırsız kısımları çarp, tüm sıfırları sona ekle. Bölmede: ortak sıfırları sil, sonra böl. İki basamaklı çarpmada ikinci satırı bir basamak sola kaydır.","t":"ses","s":null},{"k":"kart_n_carpbol_kural","m":"Çarpmada sıfırlar toplanır, bölmede ortak sıfırlar sadeleşir.","t":"ses","s":null},{"k":"kart_n_problem_gorsel","m":"Problemi bir şema ya dök: Elimde ne var? Ne harcadım? Ne kaldı?","t":"ses","s":null},{"k":"kart_n_problem_hikaye","m":"Okul, atık kâğıt kampanyasından kazandığı parayla fidan alacak. Önce bütçe, sonra harcama, sonra kalan para. Her adımı tek tek çözünce problem bir bulmaca gibi açıldı.","t":"ses","s":null},{"k":"kart_n_problem_adim","m":"1. Verilenleri ve isteneni yaz. 2. Hangi işlemler gerekiyor, belirle. 3. Ara sonucu bul. 4. Asıl soruyu çöz. 5. Cevabın mantıklı olup olmadığını kontrol et.","t":"ses","s":null},{"k":"kart_n_problem_kural","m":"Saat hesabında 1 saat eşittir 60 dakika, 100 değil!","t":"ses","s":null},{"k":"kart_n_tahmin_gorsel","m":"Sayı doğrusunda hangi onluğa daha yakın sa oraya yuvarla. Tam ortadaysa (5) yukarı.","t":"ses","s":null},{"k":"kart_n_tahmin_hikaye","m":"Mert markette 47 TL'lik ürün aldı. Yaklaşık 50 TL dedi çünkü 47, 40'tan çok 50'ye yakın. Hızlı tahmin, cebindeki paranın yetip yetmeyeceğini hemen gösterdi!","t":"ses","s":null},{"k":"kart_n_tahmin_adim","m":"Hangi basamağa yuvarlanacağını bul. Onun sağındaki rakama bak. 5 veya büyükse bir artır, küçükse aynı bırak. Sağdaki tüm rakamları 0 yap.","t":"ses","s":null},{"k":"kart_n_tahmin_kural","m":"Sağdaki rakam büyük ya da eşit 5, yukarı; küçüktür 5, aşağı.","t":"ses","s":null},{"k":"kart_a_cevre_gorsel","m":"Çevre, şeklin etrafında bir tam tur atınca yürüdüğün yoldur: 4 kenarın toplamı.","t":"ses","s":null},{"k":"kart_a_cevre_hikaye","m":"Nehir, bahçesinin etrafına çit çekecek. Bahçe 8 m'ye 4 m. Etrafında yürüyerek saydı: 8 artı 4 artı 8 artı 4 eşittir 24 m çit gerekiyor!","t":"ses","s":null},{"k":"kart_a_cevre_adim","m":"Uzun ve kısa kenarı bul. Topla: uzun artı kısa. 2 ile çarp (her kenardan iki tane var). Birimi yaz: cm, m.","t":"ses","s":null},{"k":"kart_a_cevre_kural","m":"Ç eşittir 2 çarpı (a artı b). Karede Ç eşittir 4 çarpı a.","t":"ses","s":null},{"k":"kart_a_alan_gorsel","m":"Alan, şeklin içini dolduran birim karelerin sayısıdır: sıra sayısı çarpı bir sıradaki kare.","t":"ses","s":null},{"k":"kart_a_alan_hikaye","m":"Odanın zeminini kare parkelerle döşeyen usta, bir sıraya 6 parke dizdi, toplam 3 sıra yaptı. 6 çarpı 3 eşittir 18 parke dedi. İşte alan buydu!","t":"ses","s":null},{"k":"kart_a_alan_adim","m":"Uzun kenarı bul. Kısa kenarı bul. Çarp: a çarpı b. Birimi kare olarak yaz: cm kare, m kare.","t":"ses","s":null},{"k":"kart_a_alan_kural","m":"A eşittir a çarpı b. Birim: cm kare, m kare (kare birim).","t":"ses","s":null},{"k":"kart_a_cevre_alan_gorsel","m":"Aynı çevreyle farklı alanlar olabilir! Kenarlar birbirine yaklaştıkça alan büyür.","t":"ses","s":null},{"k":"kart_a_cevre_alan_hikaye","m":"Aras ile Duru'nun ikisinde de 12 m ip var. Aras 5 m ve 1 m'lik dikdörtgen yaptı: alanı 5 m kare. Duru 3 m'ye 3 m kare yaptı: alanı 9 m kare! Aynı ip, farklı alan.","t":"ses","s":null},{"k":"kart_a_cevre_alan_adim","m":"Soru etrafını mı içini mi soruyor?. Etrafı (çit, şerit, çerçeve), çevre. İçi (boya, halı, parke), alan. Doğru formülü uygula.","t":"ses","s":null},{"k":"kart_a_cevre_alan_kural","m":"Etraf, çevre (cm). İç, alan (cm kare). Aynı çevrede en büyük alan karededir.","t":"ses","s":null},{"k":"kart_f_tur_gorsel","m":"Payda bütünün kaç parçaya bölündüğünü, pay kaç parça alındığını gösterir.","t":"ses","s":null},{"k":"kart_f_tur_hikaye","m":"Bir pizza 4 dilime bölündü. Asel 1 dilim yedi: 1/4, bu bir birim kesir. Kardeşlerle 5 dilim yemek istediler ama bir pizzada 4 dilim var; ikinci pizza açıldı: 5/4 eşittir 1 tam 1/4, bu bileşik kesir!","t":"ses","s":null},{"k":"kart_f_tur_adim","m":"Pay ile paydayı karşılaştır. Pay 1, birim kesir. Pay küçüktür payda, basit kesir. Pay büyük ya da eşit payda, bileşik kesir. Bileşiği tam sayılıya çevir: payı paydaya böl.","t":"ses","s":null},{"k":"kart_f_tur_kural","m":"dörtte on bir eşittir 2 dörtte üç (11 bölü 4 eşittir 2 kalan 3). Geri: 2 çarpı 4 artı 3 eşittir 11.","t":"ses","s":null},{"k":"kart_f_denk_gorsel","m":"Aynı miktarı farklı parçalarla gösterebilirsin: 1/2 ile 2/4 aynı uzunluktadır.","t":"ses","s":null},{"k":"kart_f_denk_hikaye","m":"Ada çikolatayı 2 parçaya bölüp 1 parçasını yedi. Emir aynı çikolatayı 4 parçaya bölüp 2 parçasını yedi. Kim daha çok yedi? İkisi de aynı! 1/2 eşittir 2/4.","t":"ses","s":null},{"k":"kart_f_denk_adim","m":"Pay ve paydayı AYNI sayıyla çarp, genişletme. Pay ve paydayı AYNI sayıya böl, sadeleştirme. Asla pay ve paydaya sayı EKLEME.","t":"ses","s":null},{"k":"kart_f_denk_kural","m":"a bölü b eşittir a çarpı k bölü b çarpı k (k eşit değil 0)","t":"ses","s":null},{"k":"kart_f_ondalik_gorsel","m":"Paydası 10, virgülden sonra 1 basamak (onda). Paydası 100, 2 basamak (yüzde).","t":"ses","s":null},{"k":"kart_f_ondalik_hikaye","m":"Market fişinde 14,25 TL yazıyordu. Defne sordu: Virgül ne? Annesi: 14 tam lira ve 25 kuruş; 1 lira 100 kuruş olduğu için 25/100 lira! İşte ondalık gösterim!","t":"ses","s":null},{"k":"kart_f_ondalik_adim","m":"Paydayı 10 veya 100 yap. Payda 10 ise virgülden sonra 1 basamak, payda 100 ise 2 basamak olur. Okurken tam onda ya da tam yüzde diye oku.","t":"ses","s":null},{"k":"kart_f_ondalik_kural","m":"onda üç eşittir 0,3, yüzde üç eşittir 0,03, dörtte bir eşittir yüzde yirmi beş eşittir 0,25","t":"ses","s":null},{"k":"kart_f_yuzde_gorsel","m":"% işareti yüzde demektir: 100 eş parçadan kaç tanesi.","t":"ses","s":null},{"k":"kart_f_yuzde_hikaye","m":"Mağazada yüzde 40 indirim tabelası vardı. Kerem yüzlük tabloyu düşündü: 100 karenin 40'ı boyalı. Yani fiyatın 100'de 40'ı düşülüyordu!","t":"ses","s":null},{"k":"kart_f_yuzde_adim","m":"Kesrin paydasını 100 yap. Pay, yüzde değeridir. Ondalığa çevirmek için: % sayısını 100'e böl.","t":"ses","s":null},{"k":"kart_f_yuzde_kural","m":"yüzde 13 eşittir yüzde on üç eşittir 0,13, yüzde 5 eşittir 0,05 (0,5 değil!)","t":"ses","s":null},{"k":"kart_f_karsilastir_gorsel","m":"Paydalar eşitse payı büyük olan büyüktür. Paylar eşitse paydası küçük olan büyüktür (parçalar daha büyük).","t":"ses","s":null},{"k":"kart_f_karsilastir_hikaye","m":"Saba iki eş pasta yaptı: birini 8, birini 10 dilime böldü. Neva 10'luktan 3 dilim, Revna 8'likten 3 dilim yedi. Kim daha çok yedi? Revna! Çünkü 8'e bölünen pastanın dilimleri daha büyük.","t":"ses","s":null},{"k":"kart_f_karsilastir_adim","m":"Paydalar eşit mi?, payları karşılaştır. Paylar eşit mi?, paydası küçük olan büyük. İkisi de farklıysa paydaları eşitle (genişlet). Sonra payları karşılaştır.","t":"ses","s":null},{"k":"kart_f_karsilastir_kural","m":"Paydalar eşitse payı büyük olan büyüktür. Paylar eşitse paydası küçük olan büyüktür.","t":"ses","s":null},{"k":"kart_f_ondalik_karsilastir_gorsel","m":"Sayı doğrusunda sağdaki sayı daha büyüktür. 0,7 eşittir 0,70 büyüktür 0,58.","t":"ses","s":null},{"k":"kart_f_ondalik_karsilastir_hikaye","m":"Selin süt fiyatlarına baktı: A markette 22,10 TL, B markette 21,99 TL. 99 daha büyük! dedi ama önce tam kısma bakması gerekiyordu: 21 küçüktür 22, yani B daha ucuz!","t":"ses","s":null},{"k":"kart_f_ondalik_karsilastir_adim","m":"Önce tam kısımları karşılaştır. Eşitse onda birler basamağına bak. O da eşitse yüzde birlere bak. Basamak sayısı eşit değilse sona 0 ekleyerek eşitle. Yüzde varsa hepsini aynı gösterime çevir.","t":"ses","s":null},{"k":"kart_f_ondalik_karsilastir_kural","m":"0,7 eşittir 0,70, 0,7 büyüktür 0,58, yüzde 41 büyüktür 0,4","t":"ses","s":null},{"k":"kart_s_arastirma_gorsel","m":"Araştırma 4 adımdır: Soru, Veri, Grafik, Yorum.","t":"ses","s":null},{"k":"kart_s_arastirma_hikaye","m":"Sınıf temsilcisi Nehir, Sınıfımız en çok hangi sporu seviyor? diye merak etti. Herkese sordu, sonuçları tabloya yazdı, sütun grafiği çizdi ve yorumladı: Voleybol kazandı! Tam bir istatistikçi!","t":"ses","s":null},{"k":"kart_s_arastirma_adim","m":"Bir gruba sorulabilecek, birçok cevabı olan bir soru belirle. Anket/gözlem ile veri topla veya hazır veri bul. Veriyi tablo ve grafikle göster. Sonuçları özetle ve yorumla.","t":"ses","s":null},{"k":"kart_s_arastirma_kural","m":"Araştırma sorusu: bir gruba yönelik ve birden çok cevaplı olmalı. Kişisel bilgiler gizli tutulur.","t":"ses","s":null},{"k":"kart_s_tablo_sutun_gorsel","m":"Her sütunun yüksekliği o kategorinin sıklığını gösterir. Tepeden eksene doğru bak.","t":"ses","s":null},{"k":"kart_s_tablo_sutun_hikaye","m":"Atatürk Ortaokulu Cumhuriyet Bayramı için tişört aldı. Hangi bedenden kaç tane alındığı bir tabloya yazıldı, sonra sütun grafiğine dönüştü. En uzun sütun en çok alınan bedendi!","t":"ses","s":null},{"k":"kart_s_tablo_sutun_adim","m":"Grafiğin başlığını ve eksenlerini oku. İstenen kategorinin sütununu bul. Sütunun tepesinden eksene yatay bak. Fark için çıkar, toplam için topla.","t":"ses","s":null},{"k":"kart_s_tablo_sutun_kural","m":"Uzun sütun eşittir çok tercih. Kaç fazla, çıkarma.","t":"ses","s":null},{"k":"kart_s_daire_gorsel","m":"Bütün daire eşittir tüm veri. Yarım daire 1/2, çeyrek daire 1/4.","t":"ses","s":null},{"k":"kart_s_daire_hikaye","m":"40 öğrenciye en sevdiği spor soruldu. Daire grafiğinde futbol dairenin yarısını kaplıyordu. Zeynep hemen hesapladı: 40'ın yarısı 20 öğrenci futbolu seçmiş!","t":"ses","s":null},{"k":"kart_s_daire_adim","m":"Dilimin bütünün kaçta kaçı olduğunu bul. Toplam kişi sayısını paydaya böl. Payla çarp. Tüm dilimler toplamının bütünü verdiğini kontrol et.","t":"ses","s":null},{"k":"kart_s_daire_kural","m":"Kişi sayısı eşittir toplam çarpı dilimin oranı.","t":"ses","s":null},{"k":"kart_s_okuryazar_gorsel","m":"Nokta grafiğinde her nokta bir kişidir. Bir grafiğe hemen inanma: eksenler 0'dan mı başlıyor? Kontrol et!","t":"ses","s":null},{"k":"kart_s_okuryazar_hikaye","m":"Bir reklam B markası A'dan kat kat fazla satıyor! diyordu. Ömer grafiğin eksenine baktı: 38'den başlıyordu! Gerçek fark sadece 4 taneydi. Ömer bir istatistik dedektifi oldu.","t":"ses","s":null},{"k":"kart_s_okuryazar_adim","m":"Grafiğin neyi gösterdiğini oku. Eksenin nereden başladığını kontrol et. Sadece verinin söylediğini söyle. Herkes, hiç kimse, her zaman gibi aşırı genellemelere dikkat et.","t":"ses","s":null},{"k":"kart_s_okuryazar_kural","m":"Veri sadece toplandığı grubu anlatır. Kesik eksen farkları abartabilir.","t":"ses","s":null},{"k":"kart_e_esitlik_gorsel","m":"eşittir bir terazi gibidir: iki taraf her zaman dengede.","t":"ses","s":null},{"k":"kart_e_esitlik_hikaye","m":"Aylin teraziye 5 kg ve 7 kg koydu. Diğer kefeye 9 kg koyunca terazi hâlâ eğikti. 3 kg eksik! dedi ve ekledi; terazi dengeye geldi: 5 artı 7 eşittir 9 artı 3.","t":"ses","s":null},{"k":"kart_e_esitlik_adim","m":"Bilinen tarafı hesapla. Diğer taraf da o kadar olmalı. Eksik sayıyı ters işlemle bul. Bir tarafa ne yaparsan diğerine de aynısını yap.","t":"ses","s":null},{"k":"kart_e_esitlik_kural","m":"3 artı 5 eşittir 6 artı 2 ( eşittir sonuç değil, denge işaretidir).","t":"ses","s":null},{"k":"kart_e_ozellik_gorsel","m":"6 çarpı 12 eşittir 6 çarpı 10 artı 6 çarpı 2: dikdörtgeni ikiye böl, alanları topla. Bu dağılmadır!","t":"ses","s":null},{"k":"kart_e_ozellik_hikaye","m":"Sevil Öğretmen tahtaya 49 çarpı 12 yazdı. Bir öğrenci 49 çarpı 10 eşittir 490 ve 49 çarpı 2 eşittir 98 bulup topladı: 588! Dağılma özelliği zor bir çarpmayı iki kolay çarpmaya çevirdi.","t":"ses","s":null},{"k":"kart_e_ozellik_adim","m":"Yerleri değişmiş mi?, değişme. Parantezler kaymış mı?, birleşme. Çarpan parantezin içine dağılmış mı?, dağılma. Çıkarma ve bölmede değişme özelliği YOKTUR.","t":"ses","s":null},{"k":"kart_e_ozellik_kural","m":"a çarpı b eşittir b çarpı a, (a artı b) artı c eşittir a artı (b artı c), a çarpı (b artı c) eşittir a çarpı b artı a çarpı c","t":"ses","s":null},{"k":"kart_e_us_gorsel","m":"4 kare eşittir 4 çarpı 4: 4 sıra 4 kare. 3 küp eşittir 3 çarpı 3 çarpı 3: küp şeklinde 27 top.","t":"ses","s":null},{"k":"kart_e_us_hikaye","m":"Sezen not kâğıtlarını panoya 5 sıra 5 sütun yapıştırdı: 5 çarpı 5 eşittir 25 kâğıt. Buna 5'in karesi denir ve 5 kare yazılır. Umay topları 3 çarpı 3 çarpı 3 dizip küp yaptı: 27 top, 3'ün küpü!","t":"ses","s":null},{"k":"kart_e_us_adim","m":"Kare: sayıyı kendisiyle 1 kez çarp. Küp: sayıyı kendisiyle 3 kez yan yana yazıp çarp. Asla üs ile çarpma! (5 kare eşit değil 10)","t":"ses","s":null},{"k":"kart_e_us_kural","m":"a kare eşittir a çarpı a, a küp eşittir a çarpı a çarpı a","t":"ses","s":null},{"k":"kart_e_oncelik_gorsel","m":"Sıra: Parantez, Üs, Çarpma/Bölme, Toplama/Çıkarma","t":"ses","s":null},{"k":"kart_e_oncelik_hikaye","m":"Mert 3 paket kalem (her biri 4 tane) ve 2 tane tek kalem aldı. 3 çarpı 4 artı 2 yazdı. Soldan sağa yapsa 3 çarpı 6 eşittir 18 bulurdu ama gerçekte 12 artı 2 eşittir 14 kalemi vardı. Öncelik gerçek hayatı anlatır!","t":"ses","s":null},{"k":"kart_e_oncelik_adim","m":"Önce parantez içini yap. Sonra üslü ifadeleri (kare, küp) hesapla. Sonra çarpma ve bölmeyi soldan sağa yap. En son toplama ve çıkarmayı soldan sağa yap.","t":"ses","s":null},{"k":"kart_e_oncelik_kural","m":"2 artı 3 çarpı 4 eşittir 14 (20 değil!)","t":"ses","s":null},{"k":"kart_e_oruntu_gorsel","m":"Örüntüde her adımda aynı miktar artar. Kural: ilk terim artı (adım eksi 1) çarpı artış.","t":"ses","s":null},{"k":"kart_e_oruntu_hikaye","m":"Ertuğrul kumbarasına her gün 15 TL attı: 15, 30, 45, 60. 10. gün ne kadar olur? Her gün 15 eklendiği için 10 çarpı 15 eşittir 150 TL! Ama kumbarada başta 20 TL olsaydı 20 artı 150 eşittir 170 TL olurdu.","t":"ses","s":null},{"k":"kart_e_oruntu_adim","m":"Ardışık terimlerin farkını bul (artış). İlk terimi belirle. n. terim eşittir ilk terim artı (n eksi 1) çarpı artış. Kuralı ilk terimlerle kontrol et.","t":"ses","s":null},{"k":"kart_e_oruntu_kural","m":"3, 7, 11, 15 diye giden örüntünün kuralı: 4 çarpı adım sayısı, eksi 1.","t":"ses","s":null},{"k":"kart_e_algoritma_gorsel","m":"Algoritma eşittir sıralı adımlar. Akış şemasında oklar sırayı, karar kutuları evet/hayır yollarını gösterir.","t":"ses","s":null},{"k":"kart_e_algoritma_hikaye","m":"Ayşe annesinden ayran tarifini aldı: yoğurt koy, su koy, çırp, tuz ekle, tadına bak, tuz yeterli değilse tekrar ekle. Bu bir algoritma! Sırayı karıştırsa ayran olmazdı.","t":"ses","s":null},{"k":"kart_e_algoritma_adim","m":"Adımları yazıldığı sırayla uygula. Her adımdan sonra elindeki değeri not et. Karar adımında koşulu kontrol et. Döngüde kaç kez döndüğünü işaretle.","t":"ses","s":null},{"k":"kart_e_algoritma_kural","m":"Algoritma: Başla, adımlar (sırayla), Bitir.","t":"ses","s":null},{"k":"kart_p_olay_gorsel","m":"Olasılık 0 ile 1 arasındadır: 0 eşittir imkânsız, 1 eşittir kesin, arası eşittir mümkün.","t":"ses","s":null},{"k":"kart_p_olay_hikaye","m":"Piknik günü yağmur yağar mı? Belki: mümkün. Zarla 7 atabilir miyiz? Asla: imkânsız. Yarın güneş doğacak mı? Kesinlikle: kesin!","t":"ses","s":null},{"k":"kart_p_olay_adim","m":"Olay mutlaka oluyor mu?, kesin (1). Asla olamıyor mu?, imkânsız (0). Olabilir de olmayabilir de mi?, mümkün.","t":"ses","s":null},{"k":"kart_p_olay_kural","m":"İmkânsız eşittir 0, Kesin eşittir 1, Mümkün: 0 ile 1 arası.","t":"ses","s":null},{"k":"kart_p_spektrum_gorsel","m":"Çarkta mavi dilim sayısı / tüm dilimler eşittir olasılık. Yarıdan azsa az olası, fazlaysa çok olası.","t":"ses","s":null},{"k":"kart_p_spektrum_hikaye","m":"Doğum günü çarkında 4 dilimin 3'ü mavi. Duru Mavi gelme ihtimali yüksek! dedi. Haklıydı: 3/4, yarıdan fazla, yani çok olası.","t":"ses","s":null},{"k":"kart_p_spektrum_adim","m":"İstenen durumları say. Tüm durumları say. Olasılık eşittir istenen / tüm. 1/2 ile karşılaştır: az mı, eşit mi, çok mu?","t":"ses","s":null},{"k":"kart_p_spektrum_kural","m":"Olasılık 0 ile 1 arasındadır; asla 1'den büyük olamaz.","t":"ses","s":null},{"k":"mis_isin_dogru","m":"Işın ile doğruyu karıştırma. Işının bir başlangıç noktası vardır ve tek yönde sonsuza gider. Doğru ise iki yönde de sonsuza uzar.","t":"ses","s":null},{"k":"mis_dp_dogru","m":"Doğru parçası ile doğruyu karıştırma. Doğru parçasının iki uç noktası vardır, bu yüzden uzunluğu ölçülebilir. Doğrunun ucu yoktur.","t":"ses","s":null},{"k":"mis_nokta_sayma","m":"Doğru parçalarını eksik sayma. Sadece yan yana olanları değil, aradaki noktaları atlayan doğru parçalarını da say: A-C de bir doğru parçasıdır.","t":"ses","s":null},{"k":"mis_cap_yaricap","m":"Çap ile yarıçapı karıştırma. Çap, merkezden geçip çemberin iki ucuna değer. Çap eşittir 2 çarpı yarıçap.","t":"ses","s":null},{"k":"mis_dik_yatay","m":"Dik olmak için yatay-dikey olmalı sanma. İki doğru dönük çizilse de aralarındaki açı 90 derece ise birbirine diktir. Köşedeki küçük kare işareti bunu gösterir.","t":"ses","s":null},{"k":"mis_paralel_kesisen","m":"Paralel ile kesişeni karıştırma. Paralel doğrular ne kadar uzatılırsa uzatılsın hiç kesişmez, aralarındaki uzaklık hep aynıdır.","t":"ses","s":null},{"k":"mis_aci_tur","m":"Açı türlerini karıştırma. 90 dereceden küçükse dar, tam 90 derece ise dik, 90 derece ile 180 derece arasındaysa geniş açıdır. 180 derece doğru açı, 360 derece tam açıdır.","t":"ses","s":null},{"k":"mis_iletki_ters","m":"İletkide yanlış ölçeği okuma. İletkide iki sıra sayı vardır. Açının kolu hangi taraftaki 0'dan başlıyorsa o sıradaki sayıyı oku. Açı dar görünüyorsa ölçüsü 90'dan küçük olmalı.","t":"ses","s":null},{"k":"mis_aci_kol","m":"Açıyı kol uzunluğuna göre karşılaştırma. Açının büyüklüğü kolların ne kadar uzun olduğuna değil, kolların ne kadar açıldığına bağlıdır.","t":"ses","s":null},{"k":"mis_tumler_butunler","m":"Tümler ile bütünleri karıştırma. Tümler açıların toplamı 90 derece, bütünler açıların toplamı 180 derecedir. Akılda kalsın: Tümler: Tek dik açı.","t":"ses","s":null},{"k":"mis_ters_aci","m":"Ters açıları eşit görmeme. Kesişen iki doğrunun karşı karşıya duran açılarına ters açı denir ve ölçüleri her zaman eşittir.","t":"ses","s":null},{"k":"mis_cokgen_sayi","m":"Kenar, köşe ve iç açı sayısını karıştırma. Bir çokgende kenar, köşe ve iç açı sayısı birbirine eşittir.","t":"ses","s":null},{"k":"mis_kosegen_kenar","m":"Kenarı köşegen sanma. Köşegen, yan yana OLMAYAN iki köşeyi birleştirir. Bir köşeden kendisine ve iki komşusuna köşegen çizilmez.","t":"ses","s":null},{"k":"mis_duzgun_eksik","m":"Düzgün çokgen tanımını eksik bilme. Düzgün çokgende hem bütün kenarlar hem de bütün iç açılar eşittir. Sadece kenarların eşit olması yetmez.","t":"ses","s":null},{"k":"mis_ucgen_360","m":"Üçgenin iç açılarını 360 derece sanma. Üçgenin iç açılarının toplamı 180 derecedir (bir doğru açı). 360 derece dörtgenin iç açılarının toplamıdır.","t":"ses","s":null},{"k":"mis_ucgen_sinif","m":"Üçgeni yanlış sınıflandırma. Üçgenin türüne EN BÜYÜK açısına bakarak karar ver: 90 dereceden büyükse geniş açılı, tam 90 derece ise dik, hepsi 90 dereceden küçükse dar açılı üçgendir.","t":"ses","s":null},{"k":"mis_sifir_atlama","m":"Bölükteki sıfırları atlama. Her bölük üç basamaklıdır. Okunmayan bölükleri 000 ile doldurmayı unutma.","t":"ses","s":null},{"k":"mis_boluk_kayma","m":"Bölük adlarını kaydırma. Sağdan sola: birler, binler, milyonlar, milyarlar bölüğü. Her bölükte üç basamak vardır.","t":"ses","s":null},{"k":"mis_basamak_deger","m":"Basamak değeri yerine rakamı söyleme. Basamak değeri eşittir rakam çarpı bulunduğu basamağın değeri. Örneğin 5 yüzler basamağındaysa değeri 500'dür.","t":"ses","s":null},{"k":"mis_basamak_kayma","m":"Basamağı bir kaydırma. Basamakları sağdan saymaya birlerden başla: birler, onlar, yüzler, binler.","t":"ses","s":null},{"k":"mis_cozumleme_bitisik","m":"Çözümlemede sıfırları kaybetme. Çözümlenmiş sayıyı toplarken her parçayı kendi basamağına yaz; boş kalan basamaklara 0 koy.","t":"ses","s":null},{"k":"mis_ilk_rakam","m":"Sadece ilk rakama bakarak karşılaştırma. Önce basamak sayısına bak: basamak sayısı fazla olan sayı daha büyüktür. Eşitse soldan rakam rakam karşılaştır.","t":"ses","s":null},{"k":"mis_ters_islem","m":"Bilinmeyeni bulurken ters işlemi seçmeme. Toplamda bilinmeyen terimi bulmak için toplamdan diğer terimi ÇIKAR. Çıkarmada eksileni bulmak için çıkan ile farkı TOPLA.","t":"ses","s":null},{"k":"mis_elde_unutma","m":"Eldeyi veya onluk bozmayı unutma. İşlemi basamak basamak yap; 10 ve üzeri olunca eldeyi bir sonraki basamağa ekle.","t":"ses","s":null},{"k":"mis_sifir_sayisi","m":"Kısa yoldan çarpma/bölmede sıfırları yanlış sayma. Sıfırları ayır, sıfır olmayan kısımları çarp, sonra ayırdığın TÜM sıfırları sona ekle. Bölmede ortak sıfırları sil.","t":"ses","s":null},{"k":"mis_kismi_carpim","m":"Çarpmada ikinci satırı kaydırmama. İki basamaklı sayıyla çarparken onlar basamağıyla çarptığın sonucu bir basamak sola kaydırarak yaz (aslında 10 ile çarpıyorsun).","t":"ses","s":null},{"k":"mis_saat_ondalik","m":"Saati ondalık sayı gibi çıkarma. 1 saat 60 dakikadır, 100 değil! Önce tam saate kadar olan dakikaları say, sonra kalanları ekle.","t":"ses","s":null},{"k":"mis_problem_adim","m":"Çok adımlı problemde adım atlama. Problemi adımlara ayır: Verilenler neler? İstenen ne? Önce ara sonucu bul, sonra asıl soruyu çöz.","t":"ses","s":null},{"k":"mis_yuvarlama_kesme","m":"Yuvarlarken sadece kesip atma. Yuvarlayacağın basamağın sağındaki rakama bak: 5 veya daha büyükse bir artır, 5'ten küçükse aynı bırak.","t":"ses","s":null},{"k":"mis_cevre_yarim","m":"Çevreyi hesaplarken sadece iki kenarı toplama. Çevre, şeklin etrafındaki TÜM kenarların toplamıdır. Dikdörtgenin 4 kenarı vardır: Çevre eşittir 2 çarpı (uzun kenar artı kısa kenar).","t":"ses","s":null},{"k":"mis_cevre_alan","m":"Çevre ile alanı karıştırma. Çevre bir uzunluktur (etrafını dolaşmak, cm). Alan ise yüzeyin kapladığı yerdir (içini kaplamak, cm kare).","t":"ses","s":null},{"k":"mis_birim","m":"Alan birimini yanlış yazma. Alan birim karelerle ölçülür: cm kare, m kare. Uzunluk birimi (cm, m) alan için kullanılmaz.","t":"ses","s":null},{"k":"mis_ters_cevre","m":"Çevreden kenar bulurken yarıya bölmeyi unutma. Çevre eşittir 2 çarpı (a artı b) olduğu için önce çevreyi 2'ye böl (a artı b), sonra bilinen kenarı çıkar.","t":"ses","s":null},{"k":"mis_cevre_alan_ayni","m":"Çevreleri eşitse alanları da eşittir sanma. Aynı çevreye sahip dikdörtgenlerin alanları farklı olabilir. Kenarlar birbirine yaklaştıkça alan büyür; en büyük alan kareye aittir.","t":"ses","s":null},{"k":"mis_kesir_tur","m":"Kesir türlerini karıştırma. Pay paydadan küçükse basit, pay 1 ise birim kesir, pay paydaya eşit ya da büyükse bileşik kesirdir.","t":"ses","s":null},{"k":"mis_tamsayili","m":"Bileşik ve tam sayılı kesir dönüşüm hatası. Payı paydaya böl: Bölüm tam kısım, kalan yeni pay olur, payda aynı kalır. Geri dönüş: (tam çarpı payda) artı pay.","t":"ses","s":null},{"k":"mis_denk_toplama","m":"Denk kesir için pay ve paydaya aynı sayıyı ekleme. Denk kesir için pay ve paydayı aynı sayıyla ÇARP veya BÖL. Toplamak kesrin değerini değiştirir.","t":"ses","s":null},{"k":"mis_ondalik_basamak","m":"Ondalık gösterimde basamak sayısını karıştırma. Paydası 10 ise virgülden sonra 1, paydası 100 ise 2 basamak olur: 3/100 eşittir 0,03.","t":"ses","s":null},{"k":"mis_ondalik_okunus","m":"Ondalık gösterimi yanlış okuma. Virgülden sonra 1 basamak varsa onda, 2 basamak varsa yüzde diye okunur: 4,25, dört tam yüzde yirmi beş.","t":"ses","s":null},{"k":"mis_yuzde_ondalik","m":"Yüzdeyi ondalığa yanlış çevirme. % işareti yüzde, yani paydası 100 demektir: yüzde 5 eşittir 5/100 eşittir 0,05 (0,5 değil!).","t":"ses","s":null},{"k":"mis_payda_buyuk","m":"Paydası büyük olan kesir büyüktür sanma. Payda bütünün kaç parçaya bölündüğünü gösterir. Parça sayısı arttıkça her parça KÜÇÜLÜR: 1/8 küçüktür 1/3.","t":"ses","s":null},{"k":"mis_pay_payda_ayri","m":"Kesirleri karşılaştırırken sadece paya bakma. Paydalar farklıysa önce paydaları eşitle (genişlet), sonra payları karşılaştır.","t":"ses","s":null},{"k":"mis_uzun_buyuk","m":"Basamağı çok olan ondalık sayı büyüktür sanma. Ondalık sayıları karşılaştırırken önce tam kısma, sonra onda birler basamağına bak: 0,7 büyüktür 0,58 çünkü 7 onda büyüktür 5 onda.","t":"ses","s":null},{"k":"mis_sifir_fark","m":"Sondaki sıfırın değeri değiştirdiğini sanma. Ondalık kısmın sonuna eklenen sıfır değeri değiştirmez: 0,7 eşittir 0,70 (7 onda eşittir 70 yüzde).","t":"ses","s":null},{"k":"mis_soru_tek","m":"Araştırma sorusunu tek kişiye/tek cevaba yönlendirme. İstatistiksel araştırma sorusu bir GRUBA sorulur ve birden çok farklı cevabı olabilir.","t":"ses","s":null},{"k":"mis_adim_sira","m":"Araştırma adımlarının sırasını karıştırma. Sıra: 1) Araştırma sorusunu belirle 2) Veri topla 3) Görselleştir 4) Özetle ve yorumla.","t":"ses","s":null},{"k":"mis_grafik_okuma","m":"Grafikten yanlış değer okuma. Sütunun tepesinden sola doğru düz bir çizgi çekip eksendeki değeri oku. Hangi kategoriye baktığını kontrol et.","t":"ses","s":null},{"k":"mis_fark_toplam","m":"Fark sorulduğunda toplama yapma. Kaç fazla / fark soruları çıkarma ister; toplam / hepsi soruları toplama ister.","t":"ses","s":null},{"k":"mis_dilim_oran","m":"Daire grafiğinde dilim oranını yanlış belirleme. Bütün daire eşittir tüm veri. Yarım daire 1/2, çeyrek daire 1/4'tür. Kişi sayısı eşittir toplam çarpı dilimin oranı.","t":"ses","s":null},{"k":"mis_asiri_genelleme","m":"Veriden kesin olmayan sonuç çıkarma. Grafik sadece toplanan veriyi anlatır. Herkes, her zaman gibi kesin yargılar veriyle desteklenmiyorsa doğru değildir.","t":"ses","s":null},{"k":"mis_eksen_yanilsama","m":"Kesik eksenli grafikte yanılma. Grafikteki eksen 0'dan başlamıyorsa sütun boyları yanıltıcı olabilir. Her zaman eksendeki gerçek sayıları oku.","t":"ses","s":null},{"k":"mis_esittir_sonuc","m":"eşittir işaretini sonucu yaz diye görme. eşittir işareti iki tarafın DENGEDE olduğunu gösterir. Sol taraf ne kadarsa sağ taraf da o kadar olmalı.","t":"ses","s":null},{"k":"mis_denge_bozma","m":"Eşitliğin korunumunu bilmeme. Bir eşitliğin iki tarafına da aynı işlemi yaparsan denge bozulmaz. Bir tarafa 2 eklersen diğer tarafa da 2 eklemelisin.","t":"ses","s":null},{"k":"mis_ozellik_karis","m":"İşlem özelliklerini karıştırma. Değişme: yer değiştirme (a çarpı b eşittir b çarpı a). Birleşme: gruplama ((a artı b) artı c eşittir a artı (b artı c)). Dağılma: çarpımı içeriye dağıtma (a çarpı (b artı c) eşittir a çarpı b artı a çarpı c).","t":"ses","s":null},{"k":"mis_dagilma_eksik","m":"Dağılmada sadece ilk terimi çarpma. Parantezin önündeki sayı parantez içindeki HER terimle çarpılır: 6 çarpı (10 artı 2) eşittir 6 çarpı 10 artı 6 çarpı 2.","t":"ses","s":null},{"k":"mis_cikarma_degisme","m":"Çıkarma/bölmede değişme özelliği var sanma. Değişme özelliği toplama ve çarpmada vardır. 9 eksi 4 ile 4 eksi 9 aynı değildir.","t":"ses","s":null},{"k":"mis_us_carpim","m":"Kareyi 2 ile çarpmak sanma. 5 kare eşittir 5 çarpı 5 eşittir 25 demektir, 5 çarpı 2 değil. Küp: 3 küp eşittir 3 çarpı 3 çarpı 3 eşittir 27.","t":"ses","s":null},{"k":"mis_oncelik_soldan","m":"İşlem önceliğini atlayıp soldan sağa yapma. Önce parantez, sonra üslü ifade, sonra çarpma-bölme, en son toplama-çıkarma yapılır.","t":"ses","s":null},{"k":"mis_oruntu_baslangic","m":"Örüntüde başlangıç değerini hesaba katmama. n. adım eşittir ilk terim artı (n eksi 1) çarpı artış. Sadece artış çarpı n demek ilk terimi unutmak olur.","t":"ses","s":null},{"k":"mis_oruntu_bir","m":"Örüntüde adım sayısını bir fazla sayma. 1. adımda henüz hiç artış olmadı. n. adıma gelene kadar (n eksi 1) kez artış olur.","t":"ses","s":null},{"k":"mis_algoritma_sira","m":"Algoritma adımlarını sırasız uygulama. Algoritma adımları yazıldığı sırayla, tek tek uygulanır. Her adımdan sonra elindeki sayıyı not et.","t":"ses","s":null},{"k":"mis_dongu_sayma","m":"Döngü tekrarlarını yanlış sayma. Döngünün her turunda değeri yaz ve koşulu kontrol et. Kaç kez tekrar ettiğini tek tek işaretle.","t":"ses","s":null},{"k":"mis_olay_tur","m":"Kesin, imkânsız ve mümkün olayları karıştırma. Kesin olay mutlaka olur (olasılık 1), imkânsız olay asla olmaz (0). Arada kalanlar mümkün olaylardır.","t":"ses","s":null},{"k":"mis_olasilik_buyuk","m":"Olasılığın 1'den büyük olabileceğini sanma. Olasılık her zaman 0 ile 1 arasındadır (yüzde 0 ile yüzde 100). İstenen durum sayısı tüm durumlardan fazla olamaz.","t":"ses","s":null},{"k":"mis_olasilik_oran","m":"Olasılık kesrini yanlış kurma. Olasılık eşittir istenen durum sayısı / tüm durumların sayısı. Paydaya tüm dilimleri yaz.","t":"ses","s":null},{"k":"mis_az_cok","m":"Az olası ile çok olasıyı karıştırma. 1/2'den küçük olasılıklar az olası, 1/2'den büyükler çok olasıdır. Tam 1/2 ise eşit olasıdır.","t":"ses","s":null},{"k":"mis_sifir_basta","m":"En küçük sayıyı 0 ile başlatma. Bir sayının en soldaki basamağı 0 olamaz. En küçük sayıyı yazarken önce 0 dışındaki en küçük rakamı, hemen ardından 0'ı yaz.","t":"ses","s":null},{"k":"mis_fiyat_okuma","m":"Fiyatı lira-kuruş olarak yanlış okuma. Virgülün solu lira, sağı kuruştur. 1 lira 100 kuruş olduğu için virgülden sonra hep 2 basamak yazılır: 14,50 TL, on dört lira elli kuruş.","t":"ses","s":null},{"k":"sfx_ok","m":"short bright magical chime with a sparkle, cheerful correct answer sound for a children's math game, clean, no voice","t":"efekt","s":1.0},{"k":"sfx_bad","m":"soft gentle low wooden bonk, friendly and not harsh, mild oops sound for a children's game, no buzzer, no voice","t":"efekt","s":0.8},{"k":"sfx_fire","m":"quick rising whoosh with fiery crackle and bright chime, combo streak sound for a kids game, energetic, no voice","t":"efekt","s":1.5},{"k":"sfx_unstop","m":"triumphant short brass and bell fanfare with sparkles, unstoppable streak celebration for a kids game, no voice","t":"efekt","s":2.0},{"k":"sfx_legend","m":"epic joyful orchestral victory fanfare with fireworks pops and shimmering bells, legendary achievement in a kids game, no voice","t":"efekt","s":3.0},{"k":"sfx_grow","m":"warm magical growing sound, plant sprouting with soft rising harp glissando, encouraging, no voice","t":"efekt","s":1.5},{"k":"sfx_win","m":"happy level complete jingle with xylophone and bells, kids learning game, bright and short, no voice","t":"efekt","s":2.5},{"k":"sfx_badge","m":"shiny badge unlocked sound, metallic sparkle and ascending bells, kids game reward, no voice","t":"efekt","s":1.5},{"k":"sfx_swoosh","m":"soft airy swoosh transition, light and quick, mobile game screen change, no voice","t":"efekt","s":0.6}]$j$::jsonb) x
